<#
nessus2report.ps1
One or two .nessus files in (External and/or Internal), one completed EIVA .docx report out.
The Abacode report template is built into this script. Pure PowerShell, no Python, installs nothing.
Works in Windows PowerShell 5.1 and PowerShell 7.

Usage (every flag is optional; anything missing is prompted for):
  .\nessus2report.ps1 -e external.nessus -i internal.nessus -c "Acme Health Inc" -a ACME -r assessment

  -e  external .nessus file (fills the EVA sections)
  -i  internal .nessus file (fills the IVA sections)
  -c  customer full name
  -a  customer abbreviation (used in the header and body)
  -r  assessment | scan   (scan = the trimmed Executive Summary scan report with quarter dates)
  -d  cover date text (default: today's date)
  -o  output .docx path
  -n  leave out Informational findings without asking

If Microsoft Word is installed, the Table of Contents page numbers are filled in automatically.
Otherwise Word fills them in when you open the report and click Yes to update fields.
#>
param(
    [Alias('e')][string]$External,
    [Alias('i')][string]$Internal,
    [Alias('c')][string]$Customer,
    [Alias('a')][string]$Abbr,
    [Alias('r')][string]$ReportType,
    [Alias('d')][string]$CoverDate,
    [Alias('o')][string]$OutFile,
    [Alias('n')][switch]$NoInfo,
    [Alias('h')][switch]$Help
)

$ErrorActionPreference = 'Stop'
Add-Type -AssemblyName System.IO.Compression
Add-Type -AssemblyName System.IO.Compression.FileSystem

$W   = 'http://schemas.openxmlformats.org/wordprocessingml/2006/main'
$XNS = 'http://www.w3.org/XML/1998/namespace'
$SEVS = @('Critical', 'High', 'Medium', 'Low', 'Informational')
$SEV_COLOR = @{ Critical = 'C00000'; High = 'FF0000'; Medium = 'ED7D31'; Low = '4472C4'; Informational = '808080' }
# Custom criticality overrides carried over from Parse-Nessus.ps1
$OVERRIDES = @{ 'Server Message Block (SMB) Protocol Version 1 Enabled (uncredentialed check)' = 'High' }
# SSL/TLS findings (matches "SSL", "TLS", "SSLv3", "TLSv1.0" etc. but not "OpenSSL" version/patch findings)
$TLS_RE = '(?<![A-Za-z])(SSL|TLS)'
$EN = [char]0x2013
$INV = [Globalization.CultureInfo]::InvariantCulture

function Clean-Path([string]$p) {
    if (-not $p) { return '' }
    return $p.Trim().Trim('"').Trim("'").Trim()
}

# ======================================================================== parse .nessus
function Parse-Time($tags, $key) {
    $ts = $tags[$key + '_TIMESTAMP']
    if ($ts -and $ts -match '^\d+$') { return [DateTimeOffset]::FromUnixTimeSeconds([long]$ts).LocalDateTime }
    $v = $tags[$key]
    if ($v) {
        $v = ($v.Trim() -replace '\s+', ' ') -replace '^[A-Za-z]{3} ', ''   # drop the weekday
        $out = [datetime]::MinValue
        if ([datetime]::TryParseExact($v, 'MMM d HH:mm:ss yyyy', $INV, 'None', [ref]$out)) { return $out }
    }
    return $null
}

function Sev-Index($s) { return [array]::IndexOf($SEVS, $s) }

function Parse-Nessus([string]$path, [string]$prefix) {
    $x = New-Object System.Xml.XmlDocument
    $x.XmlResolver = $null
    $x.Load((Resolve-Path $path).Path)
    $findings = [ordered]@{}
    $starts = New-Object System.Collections.ArrayList
    $ends = New-Object System.Collections.ArrayList
    foreach ($rh in $x.SelectNodes('//ReportHost')) {
        $tags = @{}
        foreach ($t in $rh.SelectNodes('HostProperties/tag')) { $tags[$t.GetAttribute('name')] = $t.InnerText }
        $rname = $rh.GetAttribute('name')
        $ip = if ($tags['host-ip']) { $tags['host-ip'] } else { $rname }
        $fqdn = if ($tags['host-fqdn']) { $tags['host-fqdn'] } elseif ($rname -ne $ip) { $rname } else { '' }
        $hostLabel = if ($fqdn -and $fqdn -ne $ip) { "$ip ($fqdn)" } else { $ip }
        $s = Parse-Time $tags 'HOST_START'; if ($s) { [void]$starts.Add($s) }
        $e = Parse-Time $tags 'HOST_END';   if ($e) { [void]$ends.Add($e) }
        foreach ($ri in $rh.SelectNodes('ReportItem')) {
            $name = $ri.GetAttribute('pluginName').Trim()
            $rfn = $ri.SelectSingleNode('risk_factor')
            $rf = if ($rfn) { $rfn.InnerText.Trim() } else { 'None' }
            $sev = if ($OVERRIDES.ContainsKey($name)) { $OVERRIDES[$name] } else { $rf }
            if ($sev -in @('None', 'Info', '')) { $sev = 'Informational' }
            if ($SEVS -notcontains $sev) { $sev = 'Informational' }
            if ($script:NoInfoFinal -and $sev -eq 'Informational') { continue }
            $pid_ = $ri.GetAttribute('pluginID')
            if (-not $findings.Contains($pid_)) {
                $dn = $ri.SelectSingleNode('description'); $sn = $ri.SelectSingleNode('solution')
                $findings[$pid_] = [pscustomobject]@{
                    name = $name; sev = $sev
                    desc = if ($dn) { $dn.InnerText.Trim() } else { '' }
                    sol  = if ($sn) { $sn.InnerText.Trim() } else { '' }
                    hosts = [ordered]@{}; assets_text = $null; id = $null
                }
            } elseif ((Sev-Index $sev) -lt (Sev-Index $findings[$pid_].sev)) {
                $findings[$pid_].sev = $sev
            }
            $f = $findings[$pid_]
            if (-not $f.hosts.Contains($hostLabel)) { $f.hosts[$hostLabel] = New-Object System.Collections.Generic.HashSet[string] }
            $port = $ri.GetAttribute('port'); $proto = $ri.GetAttribute('protocol')
            if ($port -and $port -ne '0') { [void]$f.hosts[$hostLabel].Add("$port/$proto") }
        }
    }

    # Roll every SSL/TLS finding into a single "Multiple SSL/TLS Issues" finding
    $tls = @($findings.Keys | Where-Object { $findings[$_].name -cmatch $TLS_RE })
    if ($tls.Count -gt 0) {
        $best = ($tls | ForEach-Object { Sev-Index $findings[$_].sev } | Measure-Object -Minimum).Minimum
        $sev = $SEVS[[int]$best]
        foreach ($k in $tls) { $findings.Remove($k) }
        $findings['__tls__'] = [pscustomobject]@{
            name = 'Multiple SSL/TLS Issues'; sev = $sev
            desc = "Several Hosts have $($sev.ToLower()) severity vulnerabilities concerning SSL/TLS encryption configuration. Review the accompanying reports for a detailed list of vulnerabilities and their affected hosts."
            sol  = 'Review SSL configuration, tracking, and testing process, and implement best practices around internet-facing sites and then internal assets. Many hosts are affected by more than one vulnerability. Consider using a dependable Certificate Authority (CA) that is subject to rigorous third-party auditing to maintain their position in major operating system and root certificate programs.'
            hosts = [ordered]@{}
            assets_text = 'Multiple assets on the target network are affected by these vulnerabilities. Please see accompanying files for more information.'
            id = $null
        }
    }

    $ordered = @($findings.Values | Sort-Object @{ Expression = { Sev-Index $_.sev } }, @{ Expression = { $_.name.ToLower() } })
    for ($n = 0; $n -lt $ordered.Count; $n++) { $ordered[$n].id = '{0}-{1:D2}' -f $prefix, ($n + 1) }
    $counts = @{}; foreach ($s in $SEVS) { $counts[$s] = @($ordered | Where-Object { $_.sev -eq $s }).Count }

    $targets = ''
    foreach ($p in $x.SelectNodes('//preference')) {
        $pn = $p.SelectSingleNode('name')
        if ($pn -and $pn.InnerText -eq 'TARGET') { $targets = $p.SelectSingleNode('value').InnerText }
    }
    $tlist = @($targets -split '[,\n]' | ForEach-Object { $_.Trim() } | Where-Object { $_ })

    return [pscustomobject]@{
        findings = $ordered; counts = $counts; targets = $tlist
        start = if ($starts.Count) { $starts | Sort-Object | Select-Object -First 1 } else { $null }
        end   = if ($ends.Count)   { $ends   | Sort-Object | Select-Object -Last 1 } else { $null }
    }
}

function Quarter([datetime]$d) { return 'Q{0} {1}' -f ([math]::Floor(($d.Month - 1) / 3) + 1), $d.Year }

function Scope-Dates($sc) {
    $ref = if ($sc.end) { $sc.end } else { Get-Date }
    if ($script:RType -eq 'scan') { return Quarter $ref }
    $s0 = if ($sc.start) { $sc.start } else { $ref }
    $endTxt = '{0} {1}' -f $ref.Day, $ref.ToString('MMMM yyyy', $INV)
    if ($s0.Date -eq $ref.Date) { return $endTxt }
    if ($s0.Year -eq $ref.Year -and $s0.Month -eq $ref.Month) { return "$($s0.Day) $EN $endTxt" }
    if ($s0.Year -eq $ref.Year) { return "$($s0.Day) $($s0.ToString('MMMM', $INV)) $EN $endTxt" }
    return "$($s0.Day) $($s0.ToString('MMMM yyyy', $INV)) $EN $endTxt"
}

# ======================================================================== docx helpers
function Load-Part([byte[]]$bytes) {
    $d = New-Object System.Xml.XmlDocument
    $d.PreserveWhitespace = $true
    $d.XmlResolver = $null
    $ms = New-Object System.IO.MemoryStream(, $bytes)
    $d.Load($ms); $ms.Dispose()
    return $d
}

function Save-Part([System.Xml.XmlDocument]$d) {
    $ms = New-Object System.IO.MemoryStream
    $set = New-Object System.Xml.XmlWriterSettings
    $set.Encoding = New-Object System.Text.UTF8Encoding($false)
    $wr = [System.Xml.XmlWriter]::Create($ms, $set)
    $d.Save($wr); $wr.Close()
    return $ms.ToArray()
}

function New-Ns([System.Xml.XmlDocument]$d) {
    $ns = New-Object System.Xml.XmlNamespaceManager($d.NameTable)
    $ns.AddNamespace('w', $W)
    return , $ns
}

function WEl($d, [string]$tag) { return $d.CreateElement('w', $tag, $W) }
function WSet($el, [string]$attr, [string]$val) {
    $a = $el.GetAttributeNode($attr, $W)
    if (-not $a) { $a = $el.OwnerDocument.CreateAttribute('w', $attr, $W); [void]$el.SetAttributeNode($a) }
    $a.Value = $val
}
function Set-Preserve($t) {
    $a = $t.GetAttributeNode('space', $XNS)
    if (-not $a) { $a = $t.OwnerDocument.CreateAttribute('xml', 'space', $XNS); [void]$t.SetAttributeNode($a) }
    $a.Value = 'preserve'
}
function Doc-Of($node) { if ($node -is [System.Xml.XmlDocument]) { return $node } else { return $node.OwnerDocument } }
function Get-WAttr($el, [string]$attr) { return $el.GetAttribute($attr, $W) }
function Q($node, [string]$xp) { return $node.SelectNodes($xp, $script:NSM[(Doc-Of $node)]) }
function Q1($node, [string]$xp) { return $node.SelectSingleNode($xp, $script:NSM[(Doc-Of $node)]) }
function Same($a, $b) { return [object]::ReferenceEquals($a, $b) }

function Text($el) { return (@(Q $el './/w:t') | ForEach-Object { $_.InnerText }) -join '' }
function Own-Ts($p) { return @(Q $p './/w:t' | Where-Object { Same (Q1 $_ 'ancestor::w:p[1]') $p }) }
function Unhighlight($run) { foreach ($h in @(Q $run './/w:highlight')) { [void]$h.ParentNode.RemoveChild($h) } }
function Style($p) { $s = Q1 $p 'w:pPr/w:pStyle'; if ($s) { return Get-WAttr $s 'val' } else { return '' } }
function Has-Pb($el) { return ($el -and $el.LocalName -eq 'p' -and (Q1 $el ".//w:br[@w:type='page']")) }
function Next-El($el) { $n = $el.NextSibling; while ($n -and $n.NodeType -ne 'Element') { $n = $n.NextSibling }; return $n }
function Prev-El($el) { $n = $el.PreviousSibling; while ($n -and $n.NodeType -ne 'Element') { $n = $n.PreviousSibling }; return $n }
function Next-Tbl($el) { $n = Next-El $el; while ($n -and $n.LocalName -ne 'tbl') { $n = Next-El $n }; return $n }
function Children($el) { return @($el.ChildNodes | Where-Object { $_.NodeType -eq 'Element' }) }

function Replace-In($root, [string]$old, [string]$new) {
    foreach ($p in @(Q $root '//w:p')) {
        while ($true) {
            $ts = Own-Ts $p
            $full = ($ts | ForEach-Object { $_.InnerText }) -join ''
            $idx = $full.IndexOf($old)
            if ($idx -lt 0) { break }
            $end = $idx + $old.Length; $pos = 0; $spans = @()
            foreach ($t in $ts) {
                $s = $t.InnerText; $a = $pos; $b = $pos + $s.Length; $pos = $b
                if ($b -gt $idx -and $a -lt $end) {
                    $spans += , @($t, ([math]::Max($idx, $a) - $a), ([math]::Min($end, $b) - $a))
                }
            }
            $hostT = ($spans | Sort-Object { $_[2] - $_[1] } -Descending | Select-Object -First 1)[0]
            foreach ($sp in $spans) {
                $t = $sp[0]; $s = $t.InnerText
                $mid = if (Same $t $hostT) { $new } else { '' }
                $t.InnerText = $s.Substring(0, $sp[1]) + $mid + $s.Substring($sp[2])
                Set-Preserve $t
            }
            Unhighlight $hostT.ParentNode
        }
    }
}

function Set-ParaText($p, [string]$value) {
    $runs = @(Q $p './/w:r[w:t]')
    for ($k = 1; $k -lt $runs.Count; $k++) { [void]$runs[$k].ParentNode.RemoveChild($runs[$k]) }
    $t = Q1 $runs[0] 'w:t'; $t.InnerText = $value
    Set-Preserve $t
    Unhighlight $runs[0]
}

function Strip-Bookmarks($el) {
    foreach ($b in @(Q $el './/w:bookmarkStart | .//w:bookmarkEnd')) { [void]$b.ParentNode.RemoveChild($b) }
    return $el
}

function Remove-All($els) {
    $ids = @{}
    foreach ($e in $els) { foreach ($b in @(Q $e './/w:bookmarkStart | .//w:bookmarkEnd')) { $ids[(Get-WAttr $b 'id')] = 1 } }
    foreach ($e in $els) { if ($e.ParentNode) { [void]$e.ParentNode.RemoveChild($e) } }
    foreach ($b in @(Q $script:doc '//w:bookmarkStart | //w:bookmarkEnd')) {
        if ($ids.ContainsKey((Get-WAttr $b 'id'))) { [void]$b.ParentNode.RemoveChild($b) }
    }
}

function Find-BodyPara([scriptblock]$pred) {
    foreach ($c in (Children $script:body)) { if ($c.LocalName -eq 'p' -and (& $pred $c)) { return $c } }
    return $null
}

$PPR_ORDER = @('pStyle', 'keepNext', 'keepLines', 'pageBreakBefore', 'framePr', 'widowControl', 'numPr',
    'suppressLineNumbers', 'pBdr', 'shd', 'tabs', 'suppressAutoHyphens', 'kinsoku', 'wordWrap',
    'overflowPunct', 'topLinePunct', 'autoSpaceDE', 'autoSpaceDN', 'bidi', 'adjustRightInd',
    'snapToGrid', 'spacing', 'ind', 'contextualSpacing')

function Ppr-Set($p, [string]$tag, $attrs) {
    $d = $p.OwnerDocument
    $pr = Q1 $p 'w:pPr'
    if (-not $pr) { $pr = WEl $d 'pPr'; [void]$p.PrependChild($pr) }
    $old = Q1 $pr "w:$tag"; if ($old) { [void]$pr.RemoveChild($old) }
    $el = WEl $d $tag
    if ($attrs) { foreach ($k in $attrs.Keys) { WSet $el $k $attrs[$k] } }
    $my = [array]::IndexOf($PPR_ORDER, $tag)
    foreach ($c in (Children $pr)) {
        $ci = [array]::IndexOf($PPR_ORDER, $c.LocalName)
        if ($ci -lt 0 -or $ci -gt $my) { [void]$pr.InsertBefore($el, $c); return }
    }
    [void]$pr.AppendChild($el)
}

function Set-Shading($tc, [string]$fill) {
    $tcpr = Q1 $tc 'w:tcPr'
    $shd = Q1 $tcpr 'w:shd'
    if (-not $shd) { $shd = WEl $tc.OwnerDocument 'shd'; [void]$tcpr.AppendChild($shd) }
    $shd.RemoveAllAttributes()
    WSet $shd 'val' 'clear'; WSet $shd 'color' 'auto'; WSet $shd 'fill' $fill
}

function Insert-After($anchor, $node) { [void]$anchor.ParentNode.InsertAfter($node, $anchor) }

# ======================================================================== locate template blocks
function Summary-Block([string]$pref) {
    $label = if ($pref -eq 'IVA') { 'Internal' } else { 'External' }
    $head = Find-BodyPara { param($p) (Text $p).Trim() -match "^$label Vulnerability (Assessment|Scan) Findings$" }
    $t1 = Next-Tbl $head; $t2 = Next-Tbl $t1
    return [pscustomobject]@{ head = $head; counts = $t1; table = $t2; remove = @() }
}

function Set-RemovalRanges($sbE, $sbI) {
    # External: its heading up to (not including) the Internal heading
    $rng = New-Object System.Collections.ArrayList
    $el = $sbE.head
    while ($el -and -not (Same $el $sbI.head)) { [void]$rng.Add($el); $el = Next-El $el }
    $sbE.remove = @($rng)
    # Internal: everything after the External table through the Internal table, plus trailing blanks
    $rng = New-Object System.Collections.ArrayList
    $el = Next-El $sbE.table
    while ($el) { [void]$rng.Add($el); if (Same $el $sbI.table) { break }; $el = Next-El $el }
    $el = Next-El $sbI.table
    while ($el -and $el.LocalName -eq 'p' -and -not (Text $el).Trim() -and -not (Has-Pb $el)) { [void]$rng.Add($el); $el = Next-El $el }
    $sbI.remove = @($rng)
}

function Detail-Block([string]$pref) {
    $label = if ($pref -eq 'IVA') { 'INTERNAL' } else { 'EXTERNAL' }
    $head = Find-BodyPara { param($p) (Style $p) -eq 'Heading1' -and (Text $p) -like '*DETAILED FINDINGS*' -and (Text $p) -like "*$label*" }
    if (-not $head) { return $null }   # the scan report has no detailed findings pages
    $items = New-Object System.Collections.ArrayList
    $el = Next-El $head
    while ($el -and -not (Has-Pb $el)) { [void]$items.Add($el); $el = Next-El $el }
    return [pscustomobject]@{ head = $head; items = @($items); pb = $el }
}

# ======================================================================== fill one section
function Body-Paras([string]$raw) {
    $out = New-Object System.Collections.ArrayList
    foreach ($block in [regex]::Split(($raw -replace "`r", ''), '\n\s*\n')) {
        $buf = @()
        foreach ($line in ($block -split "`n")) {
            $line = $line.Trim()
            if (-not $line) { continue }
            if ($line -match '^[-*]\s+') {
                if ($buf.Count) { [void]$out.Add(@('p', ($buf -join ' '))); $buf = @() }
                [void]$out.Add(@('b', ($line -replace '^[-*]\s+', '')))
            } else { $buf += $line }
        }
        if ($buf.Count) { [void]$out.Add(@('p', ($buf -join ' '))) }
    }
    if ($out.Count -eq 0) { [void]$out.Add(@('p', 'N/A')) }
    return , $out
}

function Ip-Key([string]$h) {
    $ip = $h.Split(' ')[0]
    $parts = $ip.Split('.')
    if ($parts.Count -eq 4 -and -not ($parts | Where-Object { $_ -notmatch '^\d+$' })) {
        return '0.' + (($parts | ForEach-Object { '{0:D3}' -f [int]$_ }) -join '.')
    }
    return '1.' + $ip
}

function Port-Key([string]$pp) { $n = $pp.Split('/')[0]; if ($n -match '^\d+$') { return [int]$n } else { return 0 } }

function Clone-P($p, $value) {
    $c = Strip-Bookmarks ($p.CloneNode($true))
    if ($null -ne $value) { Set-ParaText $c $value }
    return $c
}

function New-Bullet([string]$value) {
    $b = Clone-P $script:bulletTmpl $value
    Ppr-Set $b 'spacing' @{ before = '0'; after = '0' }
    Ppr-Set $b 'contextualSpacing' $null
    return $b
}

function Fill-Section([string]$pref, $sc) {
    $sb = $script:blocks[$pref].summary; $db = $script:blocks[$pref].detail
    $ordered = @($sc.findings); $counts = $sc.counts

    $hashes = @(Q $sb.counts './/w:t' | Where-Object { $_.InnerText -eq '#' })
    for ($k = 0; $k -lt [math]::Min($hashes.Count, 5); $k++) { $hashes[$k].InnerText = [string]$counts[$SEVS[$k]] }

    $tbl = $sb.table; $rows = @(Q $tbl 'w:tr')
    $tmpl = @{}; for ($k = 0; $k -lt 5; $k++) { $tmpl[$SEVS[$k]] = $rows[$k + 1] }
    $anchor = $rows[0]
    foreach ($f in $ordered) {
        $r = $tmpl[$f.sev].CloneNode($true)
        Set-ParaText (Q1 (@(Q $r 'w:tc')[0]) 'w:p') ('{0}: {1}' -f $f.id, $f.name)
        Insert-After $anchor $r; $anchor = $r
    }
    if ($ordered.Count -eq 0) {
        $r = $tmpl['Informational'].CloneNode($true)
        $tcs = @(Q $r 'w:tc')
        Set-ParaText (Q1 $tcs[0] 'w:p') 'No Notable Findings'
        Set-ParaText (Q1 $tcs[1] 'w:p') ''
        Set-Shading $tcs[0] 'FFFFFF'; Set-Shading $tcs[1] 'FFFFFF'
        Insert-After $anchor $r
    }
    foreach ($s in $SEVS) { [void]$tbl.RemoveChild($tmpl[$s]) }
    if (-not $db) { return , @() }

    $it = $db.items
    $labelP = $it[0]; $headP = $it[1]; $titleP = $it[2]; $bodyP = $it[3]
    $statusTitle = $it[4]; $statusBody = $it[5]; $recTitle = $it[6]; $assetsTitle = $it[8]

    $new = New-Object System.Collections.ArrayList
    $heads = New-Object System.Collections.ArrayList
    $textBlock = {
        param([string]$raw)
        $bp = Body-Paras $raw
        for ($k = 0; $k -lt $bp.Count; $k++) {
            $kind = $bp[$k][0]; $val = $bp[$k][1]
            if ($kind -eq 'p') { $el = Clone-P $bodyP $val } else {
                $el = New-Bullet $val
                $nxt = if ($k + 1 -lt $bp.Count) { $bp[$k + 1][0] } else { $null }
                if ($nxt -ne 'b') { Ppr-Set $el 'spacing' @{ before = '0'; after = '160' } }
            }
            [void]$new.Add($el)
        }
    }
    $n = 0
    foreach ($f in $ordered) {
        $lp = Clone-P $labelP $f.sev.ToUpper()
        foreach ($c in @(Q $lp './/w:color')) { WSet $c 'val' $SEV_COLOR[$f.sev] }
        Ppr-Set $lp 'keepNext' $null
        if ($n -gt 0) { Ppr-Set $lp 'pageBreakBefore' $null }   # every finding after the first starts a new page
        $hp = Clone-P $headP ('{0}: {1}' -f $f.id, $f.name)
        [void]$heads.Add($hp)
        [void]$new.Add($lp); [void]$new.Add($hp); [void]$new.Add((Clone-P $titleP $null))
        & $textBlock $f.desc
        [void]$new.Add((Clone-P $statusTitle $null)); [void]$new.Add((Clone-P $statusBody $null))
        [void]$new.Add((Clone-P $recTitle $null))
        & $textBlock $f.sol
        [void]$new.Add((Clone-P $assetsTitle $null))
        if ($f.assets_text) { [void]$new.Add((Clone-P $bodyP $f.assets_text)) }
        foreach ($h in ($f.hosts.Keys | Sort-Object { Ip-Key $_ })) {
            $ports = @($f.hosts[$h] | Sort-Object { Port-Key $_ })
            $txt = if ($ports.Count) { '{0}: {1}' -f $h, ($ports -join ', ') } else { $h }
            [void]$new.Add((New-Bullet $txt))
        }
        $n++
    }
    if ($ordered.Count -eq 0) { [void]$new.Add((Clone-P $bodyP 'No notable findings were identified.')) }

    Remove-All $it
    $anchor = $db.head
    foreach ($p in $new) { Insert-After $anchor $p; $anchor = $p }
    return , @($heads)
}

# ======================================================================== main
function Invoke-Main {
    if ($Help) { Get-Content $PSCommandPath -TotalCount 22 | Select-Object -Skip 1 | Write-Host; return }

    $ext = Clean-Path $External; $int = Clean-Path $Internal
    if (-not $ext -and -not $int) {
        $ext = Clean-Path (Read-Host 'External .nessus file (press Enter to skip)')
        $int = Clean-Path (Read-Host 'Internal .nessus file (press Enter to skip)')
    }
    if (-not $ext -and -not $int) { Write-Host '[!] At least one .nessus file is required.'; exit 1 }
    foreach ($f in @($ext, $int)) { if ($f -and -not (Test-Path -LiteralPath $f)) { Write-Host "[!] File not found: $f"; exit 1 } }

    $full = $Customer; if (-not $full) { $full = Read-Host 'Customer full name' }; $full = $full.Trim()
    $ab = $Abbr; if (-not $ab) { $ab = Read-Host 'Customer abbreviation' }; $ab = $ab.Trim()

    $rt = "$ReportType".ToLower()
    while ($rt -notmatch '^(assessment|scan|a|s)$') { $rt = (Read-Host 'Report type: Assessment or Scan? [a/s]').ToLower() }
    $script:RType = if ($rt -match '^s') { 'scan' } else { 'assessment' }

    $script:NoInfoFinal = [bool]$NoInfo
    if (-not $NoInfo) {
        $ans = Read-Host 'Skip Informational findings? [y/N]'
        if ($ans -match '^[yY]') { $script:NoInfoFinal = $true }
    }

    $inputs = [ordered]@{}
    if ($ext) { $inputs['EVA'] = (Resolve-Path -LiteralPath $ext).Path }
    if ($int) { $inputs['IVA'] = (Resolve-Path -LiteralPath $int).Path }
    $scans = [ordered]@{}
    foreach ($k in $inputs.Keys) { $scans[$k] = Parse-Nessus $inputs[$k] $k }

    $endsAll = @($scans.Values | Where-Object { $_.end } | ForEach-Object { $_.end })
    $scanRef = if ($endsAll.Count) { $endsAll | Sort-Object | Select-Object -Last 1 } else { Get-Date }
    $coverDate = if ($CoverDate) { $CoverDate } elseif ($script:RType -eq 'scan') { Quarter $scanRef } else { (Get-Date).ToString('MMMM d, yyyy', $INV) }

    # ---- open the embedded template
    $b64 = if ($script:RType -eq 'scan') { $script:ScanTemplateB64 } else { $script:TemplateB64 }
    $zipBytes = [Convert]::FromBase64String($b64)
    $zin = New-Object System.IO.Compression.ZipArchive((New-Object System.IO.MemoryStream(, $zipBytes)), 'Read')
    $files = [ordered]@{}
    foreach ($zent in $zin.Entries) {
        $s = $zent.Open(); $ms = New-Object System.IO.MemoryStream; $s.CopyTo($ms); $s.Dispose()
        $files[$zent.FullName] = $ms.ToArray()
    }
    $script:NSM = @{}
    $script:doc = Load-Part $files['word/document.xml']
    $script:NSM[$script:doc] = New-Ns $script:doc
    $script:body = Q1 $script:doc '/w:document/w:body'
    $parts = [ordered]@{ 'word/document.xml' = $script:doc }
    foreach ($name in @($files.Keys)) {
        if ($name -match '^word/(header|footer)\d*\.xml$') {
            $pd = Load-Part $files[$name]; $script:NSM[$pd] = New-Ns $pd; $parts[$name] = $pd
        }
    }

    $script:blocks = @{}
    foreach ($p in @('EVA', 'IVA')) { $script:blocks[$p] = [pscustomobject]@{ summary = (Summary-Block $p); detail = (Detail-Block $p) } }
    Set-RemovalRanges $script:blocks['EVA'].summary $script:blocks['IVA'].summary
    $script:bulletTmpl = (Find-BodyPara { param($p) (Text $p).Trim() -eq 'Denial of Service (DoS)' }).CloneNode($true)

    $findingHeads = New-Object System.Collections.ArrayList
    foreach ($k in $scans.Keys) { foreach ($h in (Fill-Section $k $scans[$k])) { [void]$findingHeads.Add($h) } }

    # ---- remove the unused section
    foreach ($p in @('EVA', 'IVA')) {
        if ($scans.Contains($p)) { continue }
        $b = $script:blocks[$p]
        Remove-All $b.summary.remove
        if ($b.detail) {
            $dl = @($b.detail.head) + $b.detail.items; if ($b.detail.pb) { $dl += $b.detail.pb }
            Remove-All $dl
        }
    }

    # ---- scope appendix
    $scopeHead = Find-BodyPara { param($p) (Text $p) -like '*APPENDIX B*' -and (Style $p) -eq 'Heading1' }
    $st = if ($scopeHead) { Next-Tbl $scopeHead } else { $null }
    if ($st -and (Text $st) -like '*#TARGET#*') {
        $trow = @(Q $st 'w:tr' | Where-Object { (Text $_) -like '*#TARGET#*' })[0]
        $anchor = $trow
        foreach ($pref in @('EVA', 'IVA')) {
            if (-not $scans.Contains($pref)) { continue }
            $tl = @($scans[$pref].targets); if ($tl.Count -eq 0) { $tl = @('See attached scan results') }
            foreach ($tgt in $tl) {
                $r = $trow.CloneNode($true); $tcs = @(Q $r 'w:tc')
                Set-ParaText (Q1 $tcs[0] 'w:p') $tgt
                Set-ParaText (Q1 $tcs[1] 'w:p') $(if ($pref -eq 'EVA') { 'E' } else { 'I' })
                Set-ParaText (Q1 $tcs[2] 'w:p') (Scope-Dates $scans[$pref])
                Insert-After $anchor $r; $anchor = $r
            }
        }
        [void]$st.RemoveChild($trow)
        $scopeHead = $null
    }
    if ($scopeHead) {
        $st = Next-Tbl $scopeHead
        foreach ($tr in @(Q $st 'w:tr' | Select-Object -Skip 1)) {
            $tcs = @(Q $tr 'w:tc'); if ($tcs.Count -lt 4) { continue }
            $code = (Text $tcs[2]).Trim()
            $pref = if ($code -eq 'E') { 'EVA' } elseif ($code -eq 'I') { 'IVA' } else { $null }
            if (-not $pref) { continue }
            if (-not $scans.Contains($pref)) { [void]$st.RemoveChild($tr); continue }
            $sc = $scans[$pref]
            $p0 = Q1 $tcs[0] 'w:p'
            $tl = @($sc.targets); if ($tl.Count -eq 0) { $tl = @('See attached scan results') }
            for ($k = 0; $k -lt $tl.Count; $k++) {
                if ($k -eq 0) {
                    $r = WEl $script:doc 'r'; $t = WEl $script:doc 't'; $t.InnerText = $tl[0]
                    [void]$r.AppendChild($t); [void]$p0.AppendChild($r)
                } else {
                    $np = $p0.CloneNode($true); Set-ParaText $np $tl[$k]; [void]$tcs[0].AppendChild($np)
                }
            }
            Set-ParaText (Q1 $tcs[3] 'w:p') (Scope-Dates $sc)
        }
    }

    # ---- scan report: current quarter row of the Plus/Delta table
    foreach ($tr in @(Q $script:doc '//w:tr' | Where-Object { (Text $_) -like '*#DELTA ROW#*' })) {
        $tot = @{}; foreach ($s in $SEVS) { $tot[$s] = 0; foreach ($sc in $scans.Values) { $tot[$s] += $sc.counts[$s] } }
        $vals = @(((Quarter $scanRef) -replace ' ', ' Scan '), $tot['Critical'], $tot['High'], $tot['Medium'], $tot['Low'],
                  ($tot['Critical'] + $tot['High'] + $tot['Medium'] + $tot['Low']))
        $cells = @(Q $tr 'w:tc')
        for ($k = 0; $k -lt [math]::Min($cells.Count, $vals.Count); $k++) { Set-ParaText (Q1 $cells[$k] 'w:p') ([string]$vals[$k]) }
    }

    # ---- global placeholders
    foreach ($root in $parts.Values) {
        Replace-In $root 'CUSTOMERFULLNAME (CUSTABBR)' "$full ($ab)"
        Replace-In $root 'CUSTOMERFULLNAME' $full
        Replace-In $root '#CUSTOMER FULL NAME#' $full
        Replace-In $root '#FULL DATE#' $coverDate
        Replace-In $root '#CUST ABBR#' $ab
        if (-not (Same $root $script:doc)) {   # header placeholder run has no styling; give it the paragraph's white Segoe UI
            foreach ($t in @(Q $root '//w:t' | Where-Object { $_.InnerText -eq $ab })) {
                $r = $t.ParentNode; $prp = Q1 $r.ParentNode 'w:pPr/w:rPr'; $rpr = Q1 $r 'w:rPr'
                if ($prp -and (-not $rpr -or -not (Q1 $rpr 'w:color'))) {
                    if ($rpr) { [void]$r.RemoveChild($rpr) }
                    $cl = $prp.CloneNode($true)
                    [void]$r.PrependChild($cl)
                }
            }
        }
        Replace-In $root 'CUSTABBR' $ab
        if ($script:RType -eq 'scan') {
            Replace-In $root 'VULNERABILITY ASSESSMENT REPORT' 'VULNERABILITY SCAN REPORT'
            Replace-In $root 'Vulnerability Assessment Report' 'Vulnerability Scan Report'
        }
    }

    # ---- Table of Contents
    $tocSdt = (Children $script:body) | Where-Object { $_.LocalName -eq 'sdt' -and (Text $_) -like '*Table of Contents*' } | Select-Object -First 1
    $content = Q1 $tocSdt 'w:sdtContent'
    $entries = @(Q $content 'w:p' | Where-Object { (Style $_) -like 'TOC*' -and (Style $_) -ne 'TOCHeading' })
    $fieldBegin = @()
    foreach ($ch in (Children $entries[0])) { if ($ch.LocalName -eq 'hyperlink') { break }; if ($ch.LocalName -eq 'r') { $fieldBegin += $ch.CloneNode($true) } }
    $toc1 = Strip-Bookmarks ($entries[1].CloneNode($true))
    $toc3src = @($entries | Where-Object { (Style $_) -eq 'TOC3' })
    $toc3 = if ($toc3src.Count) { Strip-Bookmarks ($toc3src[0].CloneNode($true)) } else { $null }
    foreach ($p in $entries) { [void]$content.RemoveChild($p) }
    $endP = @(Q $content 'w:p')[-1]

    $isFinding = @{}; foreach ($h in $findingHeads) { $isFinding[$h.GetHashCode()] = $h }
    $maxId = 0; foreach ($b in @(Q $script:doc '//w:bookmarkStart')) { $v = [int](Get-WAttr $b 'id'); if ($v -gt $maxId) { $maxId = $v } }
    $tocItems = New-Object System.Collections.ArrayList
    $seen = $false
    foreach ($c in (Children $script:body)) {
        if (Same $c $tocSdt) { $seen = $true; continue }
        if (-not $seen -or $c.LocalName -ne 'p') { continue }
        $fin = $isFinding.ContainsKey($c.GetHashCode()) -and (Same $isFinding[$c.GetHashCode()] $c)
        if ((Style $c) -eq 'Heading1' -or $fin) {
            $label = ((Text $c) -replace '\s+', ' ').Trim()
            if (-not $label) { continue }
            $maxId++
            $name = '_Toc9{0:D8}' -f $maxId
            $bs = WEl $script:doc 'bookmarkStart'; WSet $bs 'id' "$maxId"; WSet $bs 'name' $name
            $be = WEl $script:doc 'bookmarkEnd'; WSet $be 'id' "$maxId"
            $pr = Q1 $c 'w:pPr'
            if ($pr) { Insert-After $pr $bs } else { [void]$c.PrependChild($bs) }
            [void]$c.AppendChild($be)
            [void]$tocItems.Add(@($label, $name, $(if ($fin) { 3 } else { 1 })))
        }
    }
    for ($k = 0; $k -lt $tocItems.Count; $k++) {
        $label = $tocItems[$k][0]; $name = $tocItems[$k][1]; $lvl = $tocItems[$k][2]
        $p = if ($lvl -eq 3) { $toc3.CloneNode($true) } else { $toc1.CloneNode($true) }
        $hl = Q1 $p 'w:hyperlink'; WSet $hl 'anchor' $name
        $seq = @(Q $hl './/w:t | .//w:fldChar')
        $ff = 0; while ($seq[$ff].LocalName -ne 'fldChar') { $ff++ }
        $labelTs = @($seq[0..($ff - 1)] | Where-Object { $_.LocalName -eq 't' })
        $labelTs[0].InnerText = $label
        for ($j = 1; $j -lt $labelTs.Count; $j++) { $labelTs[$j].InnerText = '' }
        foreach ($ins in @(Q $p './/w:instrText')) { $ins.InnerText = " PAGEREF $name \h " }
        $numT = @($seq[$ff..($seq.Count - 1)] | Where-Object { $_.LocalName -eq 't' })[-1]; $numT.InnerText = '0'
        if ($k -eq 0) { foreach ($r in $fieldBegin) { [void]$p.InsertBefore($r.CloneNode($true), $hl) } }
        [void]$content.InsertBefore($p, $endP)
    }

    # ---- output path
    $out = $OutFile
    if (-not $out) {
        $first = @($inputs.Values)[0]
        $kind = if ($scans.Count -eq 2) { '' } elseif ($scans.Contains('EVA')) { ' External' } else { ' Internal' }
        $ref = $scanRef
        $qn = (Quarter $ref).Split(' ')[0]
        if ($script:RType -eq 'scan') {
            $safe = ($full -replace '[^A-Za-z0-9]+', '_').Trim('_')
            $name = 'Abacode_{0}_Executive_Summary_Report_{1}_{2}.docx' -f $safe, $qn, $ref.Year
        } else {
            $name = '{0}{1} EIVA {2} {3}.docx' -f $ab, $kind, $ref.Year, $qn
        }
        $out = Join-Path (Split-Path $first -Parent) $name
    }
    $out = [IO.Path]::GetFullPath($(if ([IO.Path]::IsPathRooted($out)) { $out } else { Join-Path (Get-Location).Path $out }))

    # ---- is Word available to calculate the TOC page numbers?
    $word = $null
    try { $word = New-Object -ComObject Word.Application } catch { $word = $null }

    foreach ($k in @($parts.Keys)) { $files[$k] = Save-Part $parts[$k] }
    if (-not $word) {
        $st = Load-Part $files['word/settings.xml']; $script:NSM[$st] = New-Ns $st
        if (-not (Q1 $st '/w:settings/w:updateFields')) {
            $u = WEl $st 'updateFields'; WSet $u 'val' 'true'
            $after = @('hdrShapeDefaults', 'footnotePr', 'endnotePr', 'compat', 'docVars', 'rsids')
            $nxt = (Children $st.DocumentElement) | Where-Object { $after -contains $_.LocalName } | Select-Object -First 1
            if ($nxt) { [void]$st.DocumentElement.InsertBefore($u, $nxt) } else { [void]$st.DocumentElement.AppendChild($u) }
        }
        $files['word/settings.xml'] = Save-Part $st
    }

    if (Test-Path -LiteralPath $out) { Remove-Item -LiteralPath $out -Force }
    $fs = [IO.File]::Open($out, 'CreateNew')
    $zout = New-Object System.IO.Compression.ZipArchive($fs, 'Create')
    foreach ($name in $files.Keys) {
        $zent = $zout.CreateEntry($name, 'Optimal')
        $s = $zent.Open(); $s.Write($files[$name], 0, $files[$name].Length); $s.Dispose()
    }
    $zout.Dispose(); $fs.Dispose(); $zin.Dispose()

    $pagesOk = $false
    if ($word) {
        try {
            $word.Visible = $false; $word.DisplayAlerts = 0
            $wd = $word.Documents.Open($out, $false, $false)
            foreach ($toc in $wd.TablesOfContents) { $toc.UpdatePageNumbers() }
            $wd.Save(); $wd.Close()
            $pagesOk = $true
        } catch { $pagesOk = $false }
        finally { try { $word.Quit() } catch {}; [void][Runtime.InteropServices.Marshal]::ReleaseComObject($word) }
    }

    foreach ($k in $scans.Keys) {
        $c = $scans[$k].counts
        $label = if ($k -eq 'EVA') { 'External' } else { 'Internal' }
        Write-Host ("[+] {0}: {1} findings  " -f $label, @($scans[$k].findings).Count) -NoNewline
        Write-Host (($SEVS | ForEach-Object { '{0}:{1}' -f $_.Substring(0, [math]::Min(4, $_.Length)), $c[$_] }) -join '  ')
    }
    if (-not $pagesOk) { Write-Host '[*] TOC page numbers will be filled in by Word when you open the report (click Yes when asked to update fields).' }
    Write-Host "[+] Report written to: $out"
}

